/* Guild identity and city identity remain separate; IDs preserve existing local memberships. */
function communityIdentityArt(c,{print=true,city=true}={}){if(!c)return '';return `${city?`<img class="identity-city-art" src="${c.art}" alt="" loading="lazy">`:''}${c.id==='huddle'?`<img class="identity-mascot" src="assets/pudgy-pfp.webp" alt="" aria-hidden="true">${print?'<div class="identity-pfp-print" aria-hidden="true"></div>':''}`:''}`}
traderGuildCard=function(g){const c=communityById(g.id),own=state.membership?.id===g.id;return `<article class="trader-guild-card identity-guild-card theme-${g.id} ${own?'is-mine':''}"><a class="identity-card-cover" href="#/${worldLink(g.id)}" aria-label="View ${escapeHtml(g.name)} guild">${communityIdentityArt(c)}<span class="identity-cover-shade"></span><span class="identity-city-label">${icon('map')} ${c?.city?'HOME CITY · '+escapeHtml(c.city):'COMMUNITY HOME'}</span>${own?'<span class="identity-cover-member">YOUR GUILD</span>':''}</a><div class="identity-card-content"><div class="trader-guild-identity"><span class="identity-avatar-frame"><img src="${emblem(g)}" alt="${escapeHtml(g.name)} PFP"></span><div><small>${c?.id==='huddle'?'PUDGY PENGUINS COMMUNITY':escapeHtml(c?.community||'COMMUNITY GUILD')}</small><h3>${escapeHtml(g.name)}</h3></div></div><p>${escapeHtml(c?.tag||g.description||'Your community. Your shared competition journey.')}</p><div class="trader-guild-meta"><span>${icon('users')} ${g.members.toLocaleString()} members</span><span>${g.policy==='approval'?'Approval required':'Open to join'}</span></div><div class="trader-entry-state"><i></i>${traderStatus(g)}</div><div class="trader-guild-actions">${own?link('my-guild','Open my guild '+arrow(),'primary button'):`<button class="primary" data-join="${g.id}">${g.policy==='approval'?'Apply to join':'Join guild'} ${arrow()}</button>`}${link('guild/'+g.id,'View guild '+arrow(),'text-button')}</div></div></article>`};
const identityBaseHero=traderHero;
traderHero=function(){let html=identityBaseHero();const own=state.membership&&communityById(state.membership.id);if(own?.id==='huddle'){html=html.replace('class="trader-hero"','class="trader-hero identity-personal-hero theme-huddle"').replace('<div class="trader-hero-glow"></div>','<div class="trader-hero-glow"></div>'+communityIdentityArt(own)).replace('YOUR GUILD.<br><span>YOUR NEXT CHALLENGE.</span>','PUDGY PENGUINS.<br><span>YOUR PEOPLE. YOUR TEAM.</span>').replace('XOX GUILDS · COMMUNITY DRIVEN TRADING','XOX GUILDS · YOUR PUDGY PENGUINS HOME').replace('Follow your team, know your contribution and get ready for the next round.','You’re with your people. Follow the guild, contribute to the competition and share the climb.').replace('<div class="trader-hero-proof">','<div class="identity-home-city">'+icon('map')+' HOME CITY <strong>The Huddle</strong></div><div class="trader-hero-proof">')}return html};
const identityBaseBanner=communityThemeBanner;
communityThemeBanner=function(c,own=false){if(c.id!=='huddle')return identityBaseBanner(c,own);return `<section class="community-theme-banner theme-huddle identity-community-banner">${communityIdentityArt(c)}<div class="identity-banner-overlay"></div><div class="community-banner-content"><span class="page-eyebrow">${own?'YOUR COMMUNITY HOME':'MEET THE COMMUNITY'} · XOX GUILDS</span><div><span class="identity-banner-avatar"><img src="${emblem(guildById(c.id))}" alt="Pudgy Penguins PFP"></span><h1 tabindex="-1">Pudgy Penguins</h1></div><p>A little warmth. A shared ambition. Your people, trading together.</p><span class="identity-home-city">${icon('map')} HOME CITY <strong>The Huddle</strong></span><span class="community-access-badge">${icon(own?'shield':'eye')} ${own?'You belong here · Guild member':'Public guild visit · Member areas stay private'}</span></div><div class="community-banner-actions">${own?link('my-guild','Enter my guild '+arrow(),'primary button'):`<button class="primary" data-join="huddle">Join Pudgy Penguins ${arrow()}</button>`}${link('rankings','View guild standings '+arrow(),'secondary button')}</div></section>`};
const identityBaseMemberBoard=traderMemberBoard;
traderMemberBoard=function(){let html=identityBaseMemberBoard();if(state.membership?.id==='huddle')html=html.replace('class="trader-member-board"','class="trader-member-board identity-member-board theme-huddle"').replace('<div class="trader-member-heading">','<div class="identity-member-watermark" aria-hidden="true"></div><div class="trader-member-heading">');return html};
const identityBaseShowJoin=showJoin;
showJoin=function(id){identityBaseShowJoin(id);if(id==='huddle'){const box=$('#modal-content .join-flow');if(box){box.classList.add('identity-join','theme-huddle');box.insertAdjacentHTML('afterbegin',`<div class="identity-join-art" aria-hidden="true">${communityIdentityArt(communityById(id))}</div>`);const text=box.querySelector('.modal-eyebrow');if(text)text.textContent='YOUR PEOPLE. YOUR NEXT CHAPTER.'}}};
const identityBaseWelcome=showWelcome;
showWelcome=function(g,created=false){identityBaseWelcome(g,created);if(g.id==='huddle'){const box=$('#modal-content .welcome-modal');if(box){box.classList.add('identity-welcome','theme-huddle');box.insertAdjacentHTML('afterbegin',`<div class="identity-welcome-art" aria-hidden="true">${communityIdentityArt(communityById(g.id))}</div>`);const p=box.querySelector(':scope > p');if(p)p.textContent='You’re part of the Pudgy Penguins guild. Your community home is The Huddle. Meet the team and get ready to compete together.'}}};
renderRoute(false);
